/* Minimal JSZip shim for extension export purposes
   This is a tiny implementation that supports:
   - new JSZip()
   - zip.file(name, Uint8Array | string | base64 string, {base64: true})
   - zip.folder(name)
   - zip.generateAsync({type: 'blob'}) -> Promise<Blob>

   It's a simplified wrapper using JSZip-like API implemented with native compression via pako if available.
   For portability we implement uncompressed store (no compression) with a very small ZIP writer.
*/
(function (global) {
  function TextEncoderShim() {
    return new TextEncoder();
  }
  function JSZipShim() {
    this.files = {};
  }
  JSZipShim.prototype.file = function (name, data, opts) {
    this.files[name] = { data: data, opts: opts || {} };
    return this;
  };
  JSZipShim.prototype.folder = function (name) {
    var self = this;
    return {
      file: function (fname, data, opts) {
        self.file(name + "/" + fname, data, opts);
        return this;
      },
    };
  };
  // Very small ZIP writer (no compression)
  function str2buf(str) {
    return new TextEncoder().encode(str);
  }
  function getUint8Array(input, isBase64) {
    if (input instanceof Uint8Array) return input;
    if (typeof input === "string") {
      if (isBase64) {
        // decode base64
        var binary = atob(input);
        var len = binary.length;
        var arr = new Uint8Array(len);
        for (var i = 0; i < len; i++) arr[i] = binary.charCodeAt(i);
        return arr;
      }
      return str2buf(input);
    }
    return new Uint8Array(0);
  }

  // CRC32 helper (generate once)
  function makeCRCTable() {
    var c,
      table = new Uint32Array(256);
    for (var n = 0; n < 256; n++) {
      c = n;
      for (var k = 0; k < 8; k++) {
        if (c & 1) c = 0xedb88320 ^ (c >>> 1);
        else c = c >>> 1;
      }
      table[n] = c >>> 0;
    }
    return table;
  }
  var _crcTable = makeCRCTable();
  function crc32(buf) {
    var crc = 0 ^ -1;
    for (var i = 0; i < buf.length; i++) {
      crc = (_crcTable[(crc ^ buf[i]) & 0xff] ^ (crc >>> 8)) >>> 0;
    }
    return (crc ^ -1) >>> 0;
  }
  JSZipShim.prototype.generateAsync = function (opts) {
    var files = this.files;
    var fileEntries = [];
    var offset = 0;
    var localHeaders = [];
    var centralHeaders = [];

    function writeUint32LE(arr, val, off) {
      arr[off] = val & 255;
      arr[off + 1] = (val >> 8) & 255;
      arr[off + 2] = (val >> 16) & 255;
      arr[off + 3] = (val >> 24) & 255;
    }
    function writeUint16LE(arr, val, off) {
      arr[off] = val & 255;
      arr[off + 1] = (val >> 8) & 255;
    }

    // Build file entries
    for (var name in files) {
      var entry = files[name];
      var isBase64 = entry.opts && entry.opts.base64;
      var content = getUint8Array(entry.data, isBase64);
      var nameBuf = str2buf(name);
      var localHeader = new Uint8Array(30 + nameBuf.length);
      // local file header signature
      writeUint32LE(localHeader, 0x04034b50, 0);
      // version needed to extract
      writeUint16LE(localHeader, 20, 4);
      // general purpose bit flag
      writeUint16LE(localHeader, 0, 6);
      // compression method (0 = store)
      writeUint16LE(localHeader, 0, 8);
      // file mod time/date
      writeUint16LE(localHeader, 0, 10);
      writeUint16LE(localHeader, 0, 12);
      // crc32
      var crcVal = crc32(content);
      writeUint32LE(localHeader, crcVal, 14);
      // compressed size
      writeUint32LE(localHeader, content.length, 18);
      // uncompressed size
      writeUint32LE(localHeader, content.length, 22);
      // file name length
      writeUint16LE(localHeader, nameBuf.length, 26);
      // extra field length
      writeUint16LE(localHeader, 0, 28);
      localHeader.set(nameBuf, 30);

      localHeaders.push({ header: localHeader, content: content });

      var centralHeader = new Uint8Array(46 + nameBuf.length);
      // central file header signature
      writeUint32LE(centralHeader, 0x02014b50, 0);
      // version made by
      writeUint16LE(centralHeader, 20, 4);
      // version needed
      writeUint16LE(centralHeader, 20, 6);
      // gp bit
      writeUint16LE(centralHeader, 0, 8);
      // compression
      writeUint16LE(centralHeader, 0, 10);
      // mod time/date
      writeUint16LE(centralHeader, 0, 12);
      writeUint16LE(centralHeader, 0, 14);
      // crc32
      writeUint32LE(centralHeader, crcVal, 16);
      // compressed size
      writeUint32LE(centralHeader, content.length, 20);
      // uncompressed size
      writeUint32LE(centralHeader, content.length, 24);
      // name len
      writeUint16LE(centralHeader, nameBuf.length, 28);
      // extra len
      writeUint16LE(centralHeader, 0, 30);
      // file comment len
      writeUint16LE(centralHeader, 0, 32);
      // disk number start
      writeUint16LE(centralHeader, 0, 34);
      // internal file attrs
      writeUint16LE(centralHeader, 0, 36);
      // external file attrs
      writeUint32LE(centralHeader, 0, 38);
      // relative offset of local header
      writeUint32LE(centralHeader, offset, 42);
      centralHeader.set(nameBuf, 46);

      centralHeaders.push(centralHeader);

      offset += localHeader.length + content.length;
      fileEntries.push(localHeader);
      fileEntries.push(content);
    }

    var centralSize = 0;
    for (var i = 0; i < centralHeaders.length; i++)
      centralSize += centralHeaders[i].length;
    var centralOffset = offset;
    var totalSize = offset + centralSize + 22; // end of central dir
    var out = new Uint8Array(totalSize);
    var p = 0;
    for (var i = 0; i < fileEntries.length; i++) {
      out.set(fileEntries[i], p);
      p += fileEntries[i].length;
    }
    for (var i = 0; i < centralHeaders.length; i++) {
      out.set(centralHeaders[i], p);
      p += centralHeaders[i].length;
    }
    // end of central dir
    // signature
    writeUint32LE(out, 0x06054b50, p);
    p += 4;
    // disk numbers
    writeUint16LE(out, 0, p);
    p += 2;
    writeUint16LE(out, 0, p);
    p += 2;
    // total entries
    writeUint16LE(out, centralHeaders.length, p);
    p += 2;
    writeUint16LE(out, centralHeaders.length, p);
    p += 2;
    // size of central
    writeUint32LE(out, centralSize, p);
    p += 4;
    // offset of central
    writeUint32LE(out, centralOffset, p);
    p += 4;
    // comment length
    writeUint16LE(out, 0, p);
    p += 2;

    var blob = new Blob([out], { type: "application/zip" });
    return Promise.resolve(blob);
  };

  global.JSZip = JSZipShim;
})(this);
